export type GeoBizCode = keyof typeof GEO_ERROR_CODES;

/** Use this table for bizCode branching; do not branch on HTTP code or msg. */
export const GEO_BIZ_CODE_BRANCHES = GEO_ERROR_CODES;

export function isGeoBizCode(value: string): value is GeoBizCode {
  return Object.prototype.hasOwnProperty.call(GEO_BIZ_CODE_BRANCHES, value);
}

export function getGeoBizCodeBranch(value: string) {
  return isGeoBizCode(value) ? GEO_BIZ_CODE_BRANCHES[value] : undefined;
}

